+    height: 100%;
+    min-height: 300px;
+    border-radius: 8px;
+}
+
+.hero-image {
+    height: 500px;
+}
+
+/* Product Cards */
+.product-grid {
+    display: grid;
+    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
+    gap: var(--spacing-md);
+}
+
+.product-card {
+    background-color: var(--surface-color);
+    border-radius: 8px;
+    overflow: hidden;
+    transition: transform 0.3s;
+    display: flex;
+    flex-direction: column;
+}
+
+.product-card:hover {
+    transform: translateY(-5px);
+}
+
+.product-image {
+    height: 300px;
+}
+
+.product-image.small {
+    height: 150px;
+}
+
+.product-info {
+    padding: var(--spacing-sm);
+    display: flex;
+    flex-direction: column;
+    gap: var(--spacing-xs);
+    flex-grow: 1;
+}
+
+.product-info h3 {
+    font-size: 1.1rem;
+    margin-bottom: 4px;
+}
+
+.product-info a {
+    text-decoration: none;
+    color: var(--text-primary);
+}
+
+.product-info a:hover {
+    text-decoration: underline;
+}
+
+.price {
+    font-weight: 700;
+    color: var(--accent-color);
+}
+
+.original-price {
+    text-decoration: line-through;
+    color: var(--text-secondary);
+    font-weight: 400;
+    margin-right: 5px;
+}
+
