+    border-radius: 12px;
+    padding: var(--spacing-lg);
+    display: grid;
+    grid-template-columns: 1fr 1fr;
+    gap: var(--spacing-lg);
+    align-items: center;
+}
+
+.deals-content h2 {
+    text-align: left;
+    margin-bottom: var(--spacing-sm);
+}
+
+.deals-grid {
+    display: grid;
+    grid-template-columns: 1fr 1fr;
+    gap: var(--spacing-sm);
+}
+
+/* Story Section */
+.story-container {
+    display: grid;
+    grid-template-columns: 1fr 1fr;
+    gap: var(--spacing-lg);
+    align-items: center;
+}
+
+.story-image {
+    height: 400px;
+}
+
+.story-content h2 {
+    text-align: left;
+    margin-bottom: var(--spacing-sm);
+}
+
+/* Footer */
+.site-footer {
