    position: relative;
    padding: 5px;
}

.cart-count {
    position: absolute;
    top: -5px;
    right: -5px;
    background: var(--accent-color);
    color: var(--bg-color);
    font-size: 0.7rem;
    font-weight: bold;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Buttons */
.btn {
    display: inline-block;
    padding: 0.8rem 1.5rem;
    border-radius: 4px;
    text-decoration: none;
    font-weight: 600;
    cursor: pointer;
    transition: transform 0.2s, background-color 0.2s;
    border: none;
}

.btn:active {
    transform: scale(0.98);
}

.btn-primary {
    background-color: var(--accent-color);
    color: var(--bg-color);
}

.btn-primary:hover {
    background-color: var(--accent-hover);
}

.btn-secondary {
    background-color: var(--surface-light);
    color: var(--text-primary);
}

.btn-secondary:hover {
    background-color: var(--border-color);
}

.btn-accent {
    background-color: var(--deal-color);
    color: var(--bg-color);
}

.btn-outline {
    background-color: transparent;
    border: 1px solid var(--text-primary);
    color: var(--text-primary);
}

.btn-sm {
    padding: 0.4rem 0.8rem;
    font-size: 0.9rem;
}

/* Sections */
section {
    padding: var(--spacing-xl) 0;
}

h2 {
    font-size: 2rem;
    margin-bottom: var(--spacing-lg);
    text-align: center;
}

/* Hero */
.hero {
    background-color: var(--surface-color);
    padding: var(--spacing-xl) 0;
}

.hero-container {
    display: grid;
    grid-template-columns: 1fr 1fr;
    align-items: center;
    gap: var(--spacing-lg);
}

.hero-content h1 {
    font-size: 3.5rem;
    line-height: 1.1;
    margin-bottom: var(--spacing-sm);
}

.hero-content p {
    font-size: 1.2rem;
    color: var(--text-secondary);
    margin-bottom: var(--spacing-md);
    max-width: 500px;
}

.img-placeholder {
    background: linear-gradient(135deg, #333, #555);
    width: 100%;
    height: 100%;
    min-height: 300px;
    border-radius: 8px;
}

.hero-image {
    height: 500px;
}

/* Product Cards */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: var(--spacing-md);
}

.product-card {
    background-color: var(--surface-color);
    border-radius: 8px;
    overflow: hidden;
    transition: transform 0.3s;
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    transform: translateY(-5px);
}

.product-image {
    height: 300px;
}

.product-image.small {
    height: 150px;
}

.product-info {
    padding: var(--spacing-sm);
    display: flex;
    flex-direction: column;
    gap: var(--spacing-xs);
    flex-grow: 1;
}

.product-info h3 {
    font-size: 1.1rem;
    margin-bottom: 4px;
}

.product-info a {
    text-decoration: none;
    color: var(--text-primary);
}

.product-info a:hover {
    text-decoration: underline;
}

.price {
    font-weight: 700;
    color: var(--accent-color);
}

.original-price {
    text-decoration: line-through;
    color: var(--text-secondary);
    font-weight: 400;
    margin-right: 5px;
}

/* Deals Banner */
.deals-banner {
    background: linear-gradient(to right, #1e1e1e, #2c2c2c);
    border-radius: 12px;
    padding: var(--spacing-lg);
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-lg);
    align-items: center;
}

.deals-content h2 {
    text-align: left;
    margin-bottom: var(--spacing-sm);
}

.deals-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-sm);
}

@media (max-width: 600px) {
    .deals-grid {
        grid-template-columns: 1fr;
    }
}

/* Story Section */
.story-container {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-lg);
    align-items: center;
}

.story-image {
    height: 400px;
}

.story-content h2 {
    text-align: left;
    margin-bottom: var(--spacing-sm);
}

/* Footer */
.site-footer {
    background-color: var(--surface-color);
    padding: var(--spacing-xl) 0 var(--spacing-md);
    border-top: 1px solid var(--border-color);
}

.footer-container {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr;
    gap: var(--spacing-lg);
    margin-bottom: var(--spacing-lg);
}

.footer-nav ul {
    list-style: none;
}

.footer-nav a {
    text-decoration: none;
    color: var(--text-secondary);
    display: block;
    margin-bottom: 8px;
}

.footer-nav a:hover {
    color: var(--text-primary);
}

.footer-social ul {
    display: flex;
    list-style: none;
    gap: var(--spacing-sm);
}

.footer-social a {
    text-decoration: none;
    color: var(--text-secondary);
}

.footer-bottom {
    text-align: center;
    border-top: 1px solid var(--border-color);
    padding-top: var(--spacing-md);
    color: var(--text-secondary);
    font-size: 0.9rem;
}

/* Responsive */
@media (max-width: 900px) {
    .hero-container, .deals-banner, .story-container, .footer-container {
        grid-template-columns: 1fr;
    }

    .hero-content h1 {
        font-size: 2.5rem;
    }

    .hero-image, .story-image {
        height: 300px;
    }
}

@media (max-width: 600px) {
    .header-container {
        flex-direction: column;
        gap: var(--spacing-sm);
    }

    .primary-nav ul {
        gap: var(--spacing-sm);
    }

    .search-form input {
        width: 100px;
    }
}

@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}
