", direction=None, fact=None, file_name='/workspace/sandbox/skills/building-accessible-ui/shopping-home-page--framework-vanilla-js--style-dark/google/gemini-3-flash-preview__s4/script.js', full_command_text=None, hook_message=None, intention='Edit file', new_file_contents='document.addEventListener('DOMContentLoaded', () => {
    // Cart Functionality
    const cartCountElement = document.getElementById('cart-count');
    const cartButton = document.querySelector('.cart-button');
    const addToCartButtons = document.querySelectorAll('button[aria-label^="Add to cart"]');

    let cartCount = 0;

    const updateCart = (productName) => {
        cartCount++;
        cartCountElement.textContent = cartCount;

        // Update accessible name for the cart button
        cartButton.setAttribute('aria-label', `View shopping cart, ${cartCount} item${cartCount !== 1 ? 's' : ''}`);

        // Visual feedback (optional but good)
        cartCountElement.style.transform = 'scale(1.2)';
        setTimeout(() => {
            cartCountElement.style.transform = 'scale(1)';
        }, 200);

        // Announce to AT
        // We could use an aria-live region for this, but the label update is often sufficient for sequential navigation.
        // For immediate feedback, a live region is better.
        const toast = document.createElement('div');
        toast.setAttribute('role', 'status');
        toast.setAttribute('aria-live', 'polite');
        toast.classList.add('sr-only');
        toast.textContent = `Added ${productName} to cart.`;
        document.body.appendChild(toast);
        setTimeout(() => toast.remove(), 3000);
    };

    addToCartButtons.forEach(button => {
        button.addEventListener('click', () => {
            const label = button.getAttribute('aria-label');
            const productName = label.replace('Add to cart: ', '');
            updateCart(productName);
        });
    });

    // Navigation Active State
    const navLinks = document.querySelectorAll('.primary-nav a');

    const updateActiveLink = () => {
        const currentPath = window.location.hash || '#';
        navLinks.forEach(link => {
            const isCurrent = link.getAttribute('href') === currentPath;
            if (isCurrent) {
                link.setAttribute('aria-current', 'page');
            } else {
                link.removeAttribute('aria-current');
            }
        });
    };

    window.addEventListener('hashchange', updateActiveLink);
    updateActiveLink(); // Initial check

    // Search Simulation
    const searchForm = document.querySelector('.search-form');
    searchForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const query = searchForm.querySelector('input').value;
        if (query.trim()) {
            alert(`Search functionality for "${query}" would go here.`);
        }
    });

    // Smooth scroll for nav links (keyboard accessible)
    navLinks.forEach(link => {
        link.addEventListener('click', (e) => {
            const href = link.getAttribute('href');
            if (href.startsWith('#') && href.length > 1) {
                e.preventDefault();
                const target = document.querySelector(href);
                if (target) {
                    target.scrollIntoView({ behavior: 'smooth' });
                    // Move focus to the section for AT
                    target.setAttribute('tabindex', '-1');
                    target.focus({ preventScroll: true });
                    window.location.hash = href;
                }
            }
        });
    });
});
